steps.run:
set -euo pipefail
if [[ -n "${{ inputs.release_tag || '' }}" ]]; then
  [[ "${{ github.event_name }}" == workflow_dispatch ]] || {
    echo '::error::release_tag is valid only for manual recovery'; exit 1;
  }
  tag="${{ inputs.release_tag }}"
  recovery=true
  [[ "${{ inputs.qualification_run_id }}" =~ ^[1-9][0-9]*$ ]]
  [[ "${{ inputs.qualification_run_attempt }}" =~ ^[1-9][0-9]*$ ]]
  [[ "$GITHUB_REF_TYPE" == tag && "$GITHUB_REF_NAME" == android/recovery/* ]] || {
    echo '::error::workflow-only recovery must run from an android/recovery/* tag'; exit 1;
  }
  git fetch --force --no-tags origin "+refs/tags/${GITHUB_REF_NAME}:refs/tags/${GITHUB_REF_NAME}"
  [[ "$(git cat-file -t "$GITHUB_REF_NAME")" == tag ]] || {
    echo '::error::workflow-only recovery ref must be an annotated tag'; exit 1;
  }
  [[ "$(git rev-parse "$GITHUB_REF_NAME^{commit}")" == "$GITHUB_SHA" ]] || {
    echo '::error::workflow-only recovery tag does not peel to the workflow SHA'; exit 1;
  }
else
  [[ "${{ github.ref_type }}" == tag ]] || {
    echo '::error::push trigger must be an android/v* tag'; exit 1;
  }
  tag="${{ github.ref_name }}"
  recovery=false
  [[ -z "${{ inputs.qualification_run_id || '' }}" ]]
  [[ -z "${{ inputs.qualification_run_attempt || '' }}" ]]
fi
[[ "$tag" == android/v* ]] || { echo "::error::invalid Android release tag: $tag"; exit 1; }
git fetch --force --no-tags origin "+refs/tags/${tag}:refs/tags/${tag}"
[[ "$(git cat-file -t "$tag")" == tag ]] || {
  echo "::error::$tag is not an annotated tag"; exit 1;
}
sha="$(git rev-parse "${tag}^{commit}")"
git fetch --force origin '+refs/heads/main:refs/remotes/origin/main'
git merge-base --is-ancestor "$sha" refs/remotes/origin/main || {
  echo "::error::$tag does not point to a main-reachable commit"; exit 1;
}
git merge-base --is-ancestor "$GITHUB_SHA" refs/remotes/origin/main || {
  echo '::error::workflow revision is not main-reachable'; exit 1;
}
{
  echo "tag=$tag"
  echo "release_sha=$sha"
  echo "recovery=$recovery"
} >> "$GITHUB_OUTPUT"

{
  echo "paths<<EOF"
  dist print-upload-files-from-manifest --manifest dist-manifest.json
  echo "EOF"
} >> "$GITHUB_OUTPUT"
cp dist-manifest.json "$BUILD_MANIFEST_NAME"

$ErrorActionPreference = 'Stop'
$archives = @(Get-ChildItem candidate -Recurse -File -Filter 'healthmd-cli-x86_64-pc-windows-msvc.zip')
if ($archives.Count -ne 1) { throw "expected one Windows archive, found $($archives.Count)" }
$root = Join-Path $env:RUNNER_TEMP 'healthmd-windows-sign'
Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue
python apps/cli/scripts/safe-extract-release.py $($archives[0].FullName) $root
if ($LASTEXITCODE -ne 0) { throw 'safe archive extraction failed' }
Get-ChildItem $root -Recurse -File | ForEach-Object { $_.IsReadOnly = $false }
$executables = @(Get-ChildItem $root -Recurse -File -Filter '*.exe')
$names = @($executables | ForEach-Object Name | Sort-Object)
if ($names.Count -ne 2 -or $names[0] -ne 'healthmd-mcp.exe' -or $names[1] -ne 'healthmd.exe') {
  throw "archive executable set is not exact: $($names -join ', ')"
}
"WINDOWS_SIGN_ROOT=$root" | Out-File -FilePath $env:GITHUB_ENV -Append
"WINDOWS_ARCHIVE=$($archives[0].FullName)" | Out-File -FilePath $env:GITHUB_ENV -Append

$ErrorActionPreference = 'Stop'
$ledger = Get-Content apps/cli/release-identities.json -Raw | ConvertFrom-Json
if ($ledger.windows.status -ne 'qualified' -or
    [string]::IsNullOrWhiteSpace($ledger.windows.publisher_subject) -or
    $ledger.windows.publisher_subject -cne $env:EXPECTED_SIGNER_SUBJECT) {
  throw 'committed Windows publisher identity is absent or differs from the release variable'
}
$executables = @(Get-ChildItem $env:WINDOWS_SIGN_ROOT -Recurse -File -Filter '*.exe')
foreach ($executable in $executables) {
  $signature = Get-AuthenticodeSignature -LiteralPath $executable.FullName
  if ($signature.Status -ne [System.Management.Automation.SignatureStatus]::Valid) {
    throw "invalid Authenticode signature for $($executable.Name): $($signature.Status)"
  }
  if ($null -eq $signature.SignerCertificate -or
      $signature.SignerCertificate.Subject -cne $env:EXPECTED_SIGNER_SUBJECT) {
    throw "unexpected Authenticode signer for $($executable.Name)"
  }
  if ($null -eq $signature.TimeStamperCertificate) {
    throw "missing RFC3161 timestamp for $($executable.Name)"
  }
}
$healthmd = @($executables | Where-Object Name -eq 'healthmd.exe')
if ($healthmd.Count -ne 1) { throw 'signed healthmd executable is missing' }
$credentialTarget = 'trust-state-v1.com.codybontecou.obsidianhealth.direct-cli-trust'
$credentialState = Join-Path $env:RUNNER_TEMP 'healthmd-windows-credential-upgrade'
Remove-Item $credentialState -Recurse -Force -ErrorAction SilentlyContinue
New-Item $credentialState -ItemType Directory | Out-Null
cmdkey.exe /delete:$credentialTarget | Out-Null
try {
  $env:HEALTHMD_CLI_DATA_DIR = $credentialState
  & $healthmd[0].FullName direct devices | Out-File -Encoding utf8 (Join-Path $credentialState 'before.json')
  if ($LASTEXITCODE -ne 0) { throw 'initial Credential Manager probe failed' }
  $identity = Get-Content (Join-Path $credentialState 'identity.json') -Raw | ConvertFrom-Json
  $fixtureID = '11111111-1111-4111-8111-111111111111'
  $fixture = @{
    installationID = $fixtureID
    displayName = 'Signing Fixture'
    platform = 'ios'
    reconnectSecret = [Convert]::ToBase64String((New-Object byte[] 32))
    pairedAt = 800000000.0
    lastConnectedAt = 800000000.0
  }
  $trust = @{ ownerInstallationID = $identity.installationID; trustedClients = @($fixture) } | ConvertTo-Json -Compress -Depth 4
  cmdkey.exe /generic:$credentialTarget /user:trust-state-v1 /pass:$trust | Out-Null
  if ($LASTEXITCODE -ne 0) { throw 'Credential Manager fixture creation failed' }
  & $healthmd[0].FullName direct devices | Out-File -Encoding utf8 (Join-Path $credentialState 'after.json')
  if ($LASTEXITCODE -ne 0) { throw 'signed credential upgrade probe failed' }
  $result = Get-Content (Join-Path $credentialState 'after.json') -Raw | ConvertFrom-Json
  $devices = @($result.devices)
  if ($result.schema -ne 'healthmd.direct_devices' -or $devices.Count -ne 1 -or
      $devices[0].installation_id -ne $fixtureID -or
      $devices[0].name -ne 'Signing Fixture' -or
      $devices[0].platform -ne 'ios') {
    throw 'signed credential upgrade probe did not read the seeded legacy target'
  }
} finally {
  cmdkey.exe /delete:$credentialTarget | Out-Null
  Remove-Item Env:HEALTHMD_CLI_DATA_DIR -ErrorAction SilentlyContinue
}
Remove-Item -LiteralPath $env:WINDOWS_ARCHIVE -Force
Compress-Archive -Path (Join-Path $env:WINDOWS_SIGN_ROOT '*') -DestinationPath $env:WINDOWS_ARCHIVE -CompressionLevel Optimal
$normalized = Join-Path (Resolve-Path candidate) 'healthmd-cli-x86_64-pc-windows-msvc.zip'
if ((Resolve-Path $env:WINDOWS_ARCHIVE).Path -ne $normalized) {
  Copy-Item -LiteralPath $env:WINDOWS_ARCHIVE -Destination $normalized -Force
}

$ErrorActionPreference = 'Stop'
$executables = @(Get-ChildItem unpacked -Recurse -File -Filter '*.exe')
if ($executables.Count -ne 2) { throw "expected two signed executables" }
foreach ($executable in $executables) {
  $signature = Get-AuthenticodeSignature -LiteralPath $executable.FullName
  if ($signature.Status -ne [System.Management.Automation.SignatureStatus]::Valid -or
      $null -eq $signature.TimeStamperCertificate -or
      $null -eq $signature.SignerCertificate -or
      $signature.SignerCertificate.Subject -cne $env:EXPECTED_SIGNER_SUBJECT) {
    throw "signature qualification failed for $($executable.Name)"
  }
}

$ErrorActionPreference = 'Stop'
$ledger = Get-Content apps/cli/release-identities.json -Raw | ConvertFrom-Json
if ($ledger.windows.status -ne 'qualified' -or
    $ledger.windows.publisher_subject -cne $env:EXPECTED_SIGNER_SUBJECT) {
  throw 'committed Windows publisher identity differs from the release variable'
}
$signature = Get-AuthenticodeSignature -LiteralPath $env:WINDOWS_INSTALLER
if ($signature.Status -ne [System.Management.Automation.SignatureStatus]::Valid -or
    $null -eq $signature.TimeStamperCertificate -or
    $null -eq $signature.SignerCertificate -or
    $signature.SignerCertificate.Subject -cne $env:EXPECTED_SIGNER_SUBJECT) {
  throw 'PowerShell installer signature qualification failed'
}

{
  echo 'run=true'
  echo 'ui_run=true'
  echo 'cli_run=true'
} >> "$GITHUB_OUTPUT"
